""" Pad all lists in data to the same length. """
def pad[T](data: list[list[T]], pad_id: T) -> list[list[T]] {
    width = max(len(d) for d in data);
    return [d + [pad_id] * (width - len(d)) for d in data];
}

"""Compare elements that have changed between prev_hash_dict and current_hash_dict.

Check if any elements have been added, removed or modified.
"""
def compare_elements(prev_hash_dict: dict[str, str], current_hash_dict: dict[str, str]) -> dict[str, str] {
    changed = {};
    for key in prev_hash_dict {
        elem = current_hash_dict.get(key, '');
        if elem == '' {
            changed[key] = 'deleted';
        } elif elem != prev_hash_dict[key] {
            changed[key] = 'changed';
        }
    }
    for key in current_hash_dict {
        elem = prev_hash_dict.get(key, '');
        if elem == '' {
            changed[key] = 'added';
        }
    }
    return changed;
}

""" Linear interpolation between from @a to @b as @t goes between 0 an 1. """
def lerp(a: float, b: float, t: float) -> float {
    return (1 - t) * a + t * b;
}

"""
    Return a mapping with the type as key, and the index number.
    :param types: a dictionary of types with the type name, and the message type
    :type types: dict
    :return: message mapping
    :rtype: dict
    """
def _get_message_mapping(types: dict[str, str]) -> dict[str, int] {
    message_mapping = {};
    entry_index = 2;
    for (_type, message) in types.items() {
        message_mapping[_type] = entry_index;
        entry_index += 1;
    }
    return message_mapping;
}

