"""Returns living neighbors around the cell."""
def get_living_neighbors(i: int, j: int, generation: list[list[int]]) -> int {
    living_neighbors = 0;
    neighbors = [
        (i - 1, j),
        (i + 1, j),
        (i, j - 1),
        (i, j + 1),
        (i - 1, j + 1),
        (i - 1, j - 1),
        (i + 1, j + 1),
        (i + 1, j - 1)
    ];
    for (k, l) in neighbors {
        if 0 <= k < len(generation) and 0 <= l < len(generation[0]) {
            if generation[k][l] == 1 {
                living_neighbors += 1;
            }
        }
    }
    return living_neighbors;
}

"""Convert a string to title case."""
def title_case(sentence: object) -> str {
    if not isinstance(sentence, str) {
        raise TypeError(('Invalid input %s - Input must be type string' % sentence));
    }
    if not sentence {
        raise ValueError('Cannot apply title function to empty string.');
    }
    ret = '';
    for (i, ch) in enumerate(sentence) {
        if i == 0 or sentence[i - 1] == ' ' {
            ret += ch.upper();
        } else {
            ret += ch.lower();
        }
    }
    return ret;
}

"""Mie pair potential."""
def mie(r: float, eps: float, sig: float, m: float = 12, n: float = 6) -> float {
    prefactor = m / (m - n) * (m / n) ** (n / (m - n));
    return prefactor * eps * ((sig / r) ** m - (sig / r) ** n);
}

