"""
    For curious people: regexes are very slow for parsing CIGAR strings.

    cigar: Unicode
    """
def count_cigar_ops(cigar: str) -> tuple[int, int, int, int] {
    b = 0;
    (num_m, num_i, num_d) = (0, 0, 0);
    for i in range(len(cigar)) {
        if cigar[i] <= '9' {
            continue;
        }
        assert b < i;
        count = int(cigar[b:i]);
        op = cigar[i];
        b = i + 1;
        if op == 'D' {
            num_d += count;
        } elif op == 'I' {
            num_i += count;
        } elif op in ('M', '=', 'X') {
            num_m += count;
        }
    }
    assert b == len(cigar);
    total_len = num_d + num_i + num_m;
    return (num_m, num_i, num_d, total_len);
}

"""Say if an optional argument is plainly present"""
def opt_in_argv_tail(argv_tail: list[str], concise: str, mnemonic: str) -> bool {
    assert concise or mnemonic;
    if concise {
        assert concise.startswith("-") and not concise.startswith("--");
    }
    if mnemonic {
        assert mnemonic.startswith("--") and not mnemonic.startswith("---");
    }
    for arg in argv_tail {
        if mnemonic.startswith(arg) and arg > "--" {
            return True;
        }
        if arg.startswith(concise) and not arg.startswith("--") {
            return True;
        }
    }
    return False;
}

