"""Returns a list of numbers with a certain relation to each other.

    The function divides one number into a list of d numbers [n0, n1, ...], such
    that their sum is number and the relation between the numbers is defined
    with n1 = n0 / r, n2 = n1 / r, n3 = n2 / r, ...
    """
def range_geometric_row(number: Any, d: Any, r: Any = 1.1) -> object {
    if (r <= 0) {
        raise ValueError("r must be > 0");
    }
    n0 = number / ((1 - ((1 / r) ** d)) / (1 - (1 / r)));
    numbers = [n0];
    for i in range((d - 1)) {
        numbers.append((numbers[-1] / r));
    }
    return numbers;
}

"""Performs version comparison to report if host is already at required
    version

    Args:
        version_req: Version that want to be at
        current_version: Version that host is currently at
    Returns:
        True if current_version >= version_req
        False otherwise
    Raises:
        ValueError: if version is in unsupported format
"""
def compare_version(version_req: str | None, current_version: str | None) -> bool {
    if current_version == None {
        return False;
    }
    if version_req == None {
        return True;
    }
    if current_version == version_req {
        return True;
    }
    current_vers = current_version.split(".");
    req_vers = version_req.split(".");
    num_loops = len(current_vers);
    if len(req_vers) < num_loops {
        num_loops = len(req_vers);
    }
    for index in range(num_loops) {
        if int(current_vers[index]) < int(req_vers[index]) {
            return False;
        } elif int(current_vers[index]) > int(req_vers[index]) {
            return True;
        }
    }
    if len(current_vers) > len(req_vers) {
        return True;
    } elif len(req_vers) > len(current_vers) {
        return False;
    } else {
        return True;
    }
}

"""Joins dictionaries in a consitent way

For multiple occurences of a key the  value is defined by the first key : value pair.

Arguments:
    *args: list of parameter dictonaries

Returns:
    dict: the joined dictionary
"""
def joinParameter(*args: dict[str, str | int | float | bool]) -> dict[str, str | int | float | bool] {
    key_list = [x.keys() for x in args];
    n = len(args);
    keys = [];
    values = [];
    for i in range(n) {
        values = values + [args[i][k] for k in key_list[i] if k not in keys];
        keys = keys + [k for k in key_list[i] if k not in keys];
    }
    return {keys[i]: values[i] for i in range(len(keys))};
}

