if simple is set to True, returns a CSV string, else a dict-like string
"""
def tag_to_string(gallery_tag: dict[str, list[str]], simple: bool = False) -> str {
    assert isinstance(gallery_tag, dict), "Please provide a dict like this: {'namespace':['tag1']}";
    string = "";
    if not simple {
        for (n, namespace) in enumerate(sorted(gallery_tag), 1) {
            if len(gallery_tag[namespace]) != 0 {
                if namespace != 'default' {
                    string += namespace + ":";
                }
                if namespace != 'default' and len(gallery_tag[namespace]) > 1 {
                    string += '[';
                }
                for (x, tag) in enumerate(sorted(gallery_tag[namespace]), 1) {
                    if x == len(gallery_tag[namespace]) {
                        string += tag;
                    } else {
                        string += tag + ', ';
                    }
                }
                if namespace != 'default' and len(gallery_tag[namespace]) > 1 {
                    string += ']';
                }
                if n != len(gallery_tag) {
                    string += ', ';
                }
            }
        }
    } else {
        for (n, namespace) in enumerate(sorted(gallery_tag), 1) {
            if len(gallery_tag[namespace]) != 0 {
                if namespace != 'default' {
                    string += namespace + ",";
                }
                for (x, tag) in enumerate(sorted(gallery_tag[namespace]), 1) {
                    if x == len(gallery_tag[namespace]) {
                        string += tag;
                    } else {
                        string += tag + ', ';
                    }
                }
                if n != len(gallery_tag) {
                    string += ', ';
                }
            }
        }
    }
    return string;
}

"""Return last index and length of the longest zero-free subarray."""
def longuest_sub_array(arr: list[int]) -> tuple[int, int] | None {
    sub_arrays: list[tuple[int, int]] = [];
    last_index = 0;
    length = 0;
    for (i, l) in enumerate(arr) {
        if l != 0 {
            length += 1;
            last_index = i;
        } else {
            if last_index == i - 1 {
                sub_arrays.append((last_index, length));
            }
            length = 0;
        }
    }
    if sub_arrays == [(0, 0)] {
        print('The image cannot be cropped vertically');
        return None;
    }
    return max(sub_arrays, key=lambda (p: tuple[int, int]) { p[1]; });
}

"""Merge sort, duh?

    :param list: List of things to sort
    :return: Cool sorted list
    """
def merge_sort(`list: Any) -> object {
    if (len(`list) > 1) {
        middle = len(`list) // 2;
        left = merge_sort(`list[:middle]);
        right = merge_sort(`list[middle:]);
        `list = [];
        while ((len(left) > 0) and (len(right) > 0)) {
            if (left[0] < right[0]) {
                `list.append(left[0]);
                left.pop(0);
            } else {
                `list.append(right[0]);
                right.pop(0);
            }
        }
        for item in left {
            `list.append(item);
        }
        for item in right {
            `list.append(item);
        }
    }
    return `list;
}

