"""
Determines if the three input numbers are in sequence, either low-to-high
or high-to-low (with ties acceptable).
"""
def is_monotonic(a: float, b: float, c: float) -> bool {
    if b == a {
        return True;
    } elif b == c {
        return True;
    } elif (a > b) != (c > b) {
        return True;
    } else {
        return False;
    }
}

"""dice coefficient 2nt / (na + nb)."""
def dice_coefficient(a: str, b: str) -> float {
    if not len(a) or not len(b) {
        return 0.0;
    }
    if len(a) == 1 {
        a = a + '.';
    }
    if len(b) == 1 {
        b = b + '.';
    }
    a_bigram_list = [a[i:i + 2] for i in range(len(a) - 1)];
    b_bigram_list = [b[i:i + 2] for i in range(len(b) - 1)];
    a_bigrams = set(a_bigram_list);
    b_bigrams = set(b_bigram_list);
    overlap = len(a_bigrams & b_bigrams);
    return overlap * 2.0 / (len(a_bigrams) + len(b_bigrams));
}

"""convert a non-negative integer to raw binary buffer"""
def int2bin(n: int) -> bytes {
    buf = bytearray();
    while n > 0 {
        buf.insert(0, n & 255);
        n >>= 8;
    }
    return bytes(buf);
}

