"""Generate the expected list of previous values given a list of next values."""
def generate_previous_list(next_list: list[int | None]) -> list[int | None] {
    previous_list = [None] + next_list[:-1];
    idx_last_valid = 1;
    for i in range(1, len(previous_list)) {
        if previous_list[i] is None {
            previous_list[i] = previous_list[idx_last_valid];
        } else {
            idx_last_valid = i;
        }
    }
    assert len(next_list) == len(previous_list);
    return previous_list;
}

"""
    Binary search recursive function.
    :param bs: int
        What to search
    :param arr: array
        Array of ints where to search. Array must be sorted.
    :return: string
        Position of required element or "cannot found" string
    """
def search(bs: int, arr: list[int]) -> str {
    length = len(arr);
    check_item = arr[int(length / 2)];
    if check_item == bs {
        return str(check_item) + ' is on position ' + str(arr[int(length / 2)]);
    }
    if check_item < bs {
        return search(bs, arr[int(length / 2):]);
    }
    if check_item > bs {
        return search(bs, arr[:int(length / 2)]);
    }
    return "cannot found";
}

"""Calculates the number of learner steps to do at step=num_observations."""
def _calculate_num_learner_steps(
    num_observations: int, min_observations: int, observations_per_step: float
) -> int {
    n = num_observations - min_observations;
    if n < 0 {
        return 0;
    }
    if observations_per_step > 1 {
        return int(n % int(observations_per_step) == 0);
    }
    return int(1 / observations_per_step);
}

