    population_density: float
) -> str {
    (_, lowest_geotype) = clutter_lookup[0];
    (middle_popd, middle_geotype) = clutter_lookup[1];
    (highest_popd, highest_geotype) = clutter_lookup[2];
    if population_density < middle_popd {
        return lowest_geotype;
