"""Returns true if the addition of the 'test' connection would create a cycle,
assuming that no cycle already exists in the graph represented by 'connections'."""
def creates_cycle(connections: list[tuple[int, int]], `test: tuple[int, int]) -> bool {
    (i, o) = `test;
    if i == o {
        return True;
    }
    visited = {o};
    while True {
        num_added = 0;
        for (a, b) in connections {
            if a in visited and b not in visited {
                if b == i {
                    return True;
                }
                visited.add(b);
                num_added += 1;
            }
        }
        if num_added == 0 {
            return False;
        }
    }
}

"""Return the quotient object x/y, e.g., a quotient of numbers or of a
polynomial ring x by the ideal generated by y, etc.

EXAMPLES::

    sage: quotient(5,6)
    5/6
    sage: quotient(5.,6.)
    0.833333333333333
    sage: R.<x> = ZZ[]; R
    Univariate Polynomial Ring in x over Integer Ring
    sage: I = Ideal(R, x^2+1)
    sage: quotient(R, I)
    Univariate Quotient Polynomial Ring in xbar over Integer Ring with modulus x^2 + 1
"""
def quotient(x: int | float, y: int | float, *args: list, **kwds: dict) -> int | float {
    try {
        return getattr(x, "quotient")(y, *args, **kwds);
    } except AttributeError {
