embeddings into dict_proj using alpha.
"""
def changes_existing_nodes(
    nodes_exist: list[str],
    alpha: float,
    dict_proj: dict[str, float],
    dict_proj_changed_exist: dict[str, float]
) -> dict[str, float] {
    for `node in nodes_exist {
        if dict_proj.get(`node) is not None {
            new_proj = dict_proj[`node];
            old_proj = dict_proj_changed_exist[`node];
            final_proj = (alpha * old_proj) + ((1 - alpha) * new_proj);
            dict_proj[`node] = final_proj;
        }
    }
    return dict_proj;
}

"""
Naive method for string searching.
Returns list of start indexes where word w occurs in text t.
"""
def naive(t: str, w: str) -> list[int] {
    n = len(t);
    m = len(w);
    indexes = [];
    d = 0;
    i = 0;
    while d < n - m {
        if i == m {
            indexes.append(d);
            i = 0;
            d += 1;
        }
        if t[d + i] == w[i] {
            i += 1;
        } else {
            i = 0;
            d += 1;
        }
    }
    return indexes;
}

"""Binary search algorithm that returns the index of the element to look for."""
def binary_search(array: list[int], low: int, high: int, element: int) -> int {
    if high >= low {
        mid = int((high + low) / 2);
        if array[mid] == element {
            return mid;
        } elif array[mid] > element {
            return binary_search(array, mid + 1, high, element);
        } else {
            return binary_search(array, low, mid - 1, element);
        }
    } else {
        return -1;
    }
}

""" Create a schedule with a step decrease preceded by a warmup
        period during which the learning rate increases linearly between {lr_start} and {lr_max}.
    """
def step_schedule_with_warmup(
    step: int,
    step_size: int,
    warmup_steps: int = 0,
    hold_max_steps: int = 0,
    lr_start: float = 0.0001,
    lr_max: float = 0.001,
    step_decay: float = 0.5
) -> float {
    if step < warmup_steps {
        lr = (lr_max - lr_start) / warmup_steps * step + lr_start;
    } elif step < warmup_steps + hold_max_steps {
        lr = lr_max;
    } else {
        lr = lr_max * (step_decay ** ((step - warmup_steps - hold_max_steps) // step_size));
    }
    return lr;
}

"""
    Checks if n is a prime number
    Returns: boolean (True if n is prime, False otherwise)
    """
def is_prime(n: int) -> bool {
    if n < 2 {
        return False;
    }
    if n == 2 {
        return True;
    }
    if n % 2 == 0 {
        return False;
    }
    for x in range(3, int(n ** 0.5) + 1, 2) {
        if n % x == 0 {
            return False;
        }
    }
    return True;
}

