    returned list will be   [  0 , 0 , 0 , 1 , 1 ].  This is useful
    when working with `DataSet` objects that have `collisionAction`
    set to "keepseparate".
    """
def compute_occurrence_indices(lst: list[str | int]) -> list[int] {
    lookup: dict[str | int, int] = {};
