    as dependent. That's the root.
    """
def find_root(tower: dict[str, tuple[int, list[str]]]) -> str | None {
    deps = {dep for (_, (_, holding)) in tower.items() for dep in holding};
    for (prog, (_, holding)) in tower.items() {
        if prog not in deps {
            return prog;
        }
    }
}

"""
    Group a list into groups of adjacent elements. e.g.

    > group(list("AAABBCCDBBBBA"))
    [("A", 3), ("B", 2), ("C", 2), ("D", 1), ("B", 4), ("A", 1)]
    """
def group(l: list[str]) -> list[tuple[str, int]] {
    result = [];
    previous = None;
    count = 0;
    for elem in l {
        if previous is None {
            previous = elem;
            count = 1;
        } elif previous == elem {
            count += 1;
        } else {
            result.append((previous, count));
            previous = elem;
            count = 1;
        }
    }
    if previous is not None {
        result.append((previous, count));
    }
    return result;
}

"""Returns a compact string describing the firewall rules."""
def _FirewallRulesToCell(firewall: Any) -> object {
    rules = [];
    for allowed in firewall.get('allowed', []) {
        protocol = allowed.get('IPProtocol');
        if not protocol {
            continue;
        }
        port_ranges = allowed.get('ports');
        if port_ranges {
            for port_range in port_ranges {
                rules.append('{0}:{1}'.format(protocol, port_range));
            }
        } else {
            rules.append(protocol);
        }
    }
    return ','.join(rules);
}

"""is_prime will return if a number is prime or not."""
def is_prime(num: int) -> bool {
    if num == 0 or num == 1 {
        return False;
    }
    for i in range(2, num) {
        if num % i == 0 {
            return False;
        }
    }
    return True;
}

