""" Determine whether an edit is editorial (0) or content (1).
	This is dependent on whether there are substantial additions in content volume.

	It is only a content contribution if:
		1) both text and links/urls are added (not text in isolation)
		2) images are added.
	Editorial counts:
		- words only
		- categories
		- any deletions
	"""
def determine_edit_type(values: Any, previous_values: Any) -> object {
    changes = {key: (values[key] - previous_values.get(key, 0)) for key in values};
    if (changes["images"] > 0) {
        return "content";
    } elif ((changes["words"] > 0) and ((changes["links"] + changes["urls"]) > 0)) {
        return "content";
    } else {
        return "editorial";
    }
}

"""Returns a tuple consisting of the yield value and servings value.

    Only one of these has a meaningful value while the other is set to a
    default value. If there is an integer followed optionally by the word
    'serving' or 'servings' then return this integer value as the number
    of servings, otherwise return the input value as the yield.
    """
def _get_yield_and_servings(value: Any) -> object {
    if value.lower().endswith('servings') {
        servings = value[:-8].strip();
    } elif value.lower().endswith('serving') {
        servings = value[:-7].strip();
    } else {
        servings = value;
    }
    try {
        return ('', int(servings));
    } except ValueError {
        return (value, 0);
    }
}

