"""Smaller error with slightly more compute."""
def rk4_alt_step_func(func: Any, t: Any, dt: Any, y: Any, k1: Any = None) -> object {
    if (k1 is None) {
        k1 = func(t, y);
    }
    k2 = func(
        (t + (dt / 3)), `tuple((y_ + ((dt * k1_) / 3)) for (y_, k1_) in zip(y, k1))
    );
    k3 = func(
        (t + ((dt * 2) / 3)),
        `tuple((y_ + (dt * ((k1_ / -3) + k2_))) for (y_, k1_, k2_) in zip(y, k1, k2))
    );
    k4 = func(
        (t + dt),
        `tuple(
            (y_ + (dt * ((k1_ - k2_) + k3_)))
            for (y_, k1_, k2_, k3_) in zip(y, k1, k2, k3)
        )
    );
    return `tuple(
        ((k1_ + (3 * k2_) + (3 * k3_) + k4_) * (dt / 8))
        for (k1_, k2_, k3_, k4_) in zip(k1, k2, k3, k4)
    );
}

glob PER_MILLION = 1_000_000.0;

"""Simple maths method for finding relative frequency of a word in the
focus corpus compared to the reference corpus. Frequencies are
calculated per million and N is the smoothing parameter (default N = 1)."""
def smoothed_relative_freq(
    n_focus: int,
    n_ref: int,
    size_focus: int,
    size_ref: int,
    N: int = 1
) -> float {
    f_focus = n_focus * PER_MILLION / size_focus;
    f_ref = n_ref * PER_MILLION / size_ref;
    return (f_focus + N) / (f_ref + N);
}

