import from hashlib { md5 }

"""Removes duplicates from a given data structure."""
def dedupe(duped_data: list[str | int | float | bool], encoding: str = 'utf-8') -> list[str | int | float | bool] {
    codes = set();
    deduped_data = [];
    for item in duped_data {
        hash_digest = md5(str(item).encode(encoding)).hexdigest();
        if hash_digest not in codes {
            codes.add(hash_digest);
            deduped_data.append(item);
        }
    }
    return deduped_data;
}

"""Retrieve the absolute number corresponding a color set by color_dict."""
def get_color(color_dict: dict[str, int], colors: list[list[dict[str, int]]]) -> int {
    for (i, color) in enumerate(colors) {
        for data in color {
            equal = True;
            for (k, v) in data.items() {
                if k not in color_dict or v != color_dict[k] {
                    equal = False;
                    break;
                }
            }
            if equal {
                return i;
            }
        }
    }
    return -1;
}

