"""
Arguments:
    faces ([[vIdx, ...], ...]): A face representation

Returns:
    set : A set of vertex indexes along the border of the mesh
"""
def getBorders(faces: list[list[int]]) -> set[int] {
    edge_pairs = set();
    for face in faces {
        for f in range(len(face)) {
            edge_pairs.add((face[f], face[f - 1]));
        }
    }
    borders = set();
    for ep in edge_pairs {
        if (ep[1], ep[0]) not in edge_pairs {
            borders.update(ep);
        }
    }
    return borders;
}

"""Convert degrees into hex coordinates."""
def deg2dms(val: float, delim: str = ':') -> str {
    sign = -1 if val < 0 else 1;
    d = int(sign * val);
    m = int((sign * val - d) * 60.0);
    s = ((sign * val - d) * 60.0 - m) * 60.0;
    return '{}{}{}{}{}'.format(sign * d, delim, m, delim, s);
}

"""
helper function for run(), evaluates winner of pairs, but faster (by
about two orders of magnitude) than _graph() (now deprecated)
"""
def _faster_comp(
    candidates: set[int],
    pairs: list[tuple[int, int]]
) -> set[int] {
    edges = set();
    children = set();
    for (i, j) in pairs {
        if (
            i in candidates
            and j in candidates
            and i not in children
            and (j, i) not in edges
        ) {
            children.add(j);
            edges.add((i, j));
        }
    }
    winners = set();
    for c in candidates {
        if c not in children {
            winners.add(c);
        }
    }
    return winners;
}

