"""
Implements the minimum set cover algorithm to find non-overlapping sets
out of the 80 ribosomal sampled regions
"""
def get_minimum_set_cover(nodelist: list[int], listofsubsets: list[set[int]]) -> list[set[int]] | None {
    indices = set(range(len(nodelist)));
    elems = set(e for s in listofsubsets for e in s);
    if elems != indices {
        return None;
    }
    covered = set();
    cover: list[set[int]] = [];
    while covered != elems {
        subset = max(listofsubsets, key=lambda (s: set[int]) { len(s - covered); });
        cover.append(subset);
        covered |= subset;
    }
    return cover;
}

"""
Compute the dependencies of each path var.
"""
def to_dependencies_of(g: dict[str, list[str]]) -> dict[str, list[str]] {
    deps: dict[str, set[str]] = {};
    for (k, vertices) in g.items() {
        for v in vertices {
            if v not in deps {
                deps[v] = set();
            }
            deps[v].add(k);
        }
    }
    return {k: sorted(v) for (k, v) in deps.items()};
}

"""
Converts a string to a list with more flexibility than string.split()
by looking for both brackets of type (,),[,],{,} and commas.
"""
def strtolist(string: str) -> list[int | float] {
    out: list[int | float] = [];
    temp = '';
    brackets = ['(', ')', '[', ']', '{', '}'];
    for char in list(string) {
        if char not in brackets and char != ',' {
            temp += char;
        }
        if char == ',' {
            try {
                out.append(int(temp));
            } except ValueError {
                out.append(float(temp));
            }
            temp = '';
        }
    }
    if len(temp) != 0 {
        try {
            out.append(int(temp));
        } except ValueError {
            out.append(float(temp));
        }
    }
    return out;
}

