"""Does given bytes object start with the subsequence prefix?

    Compiling bytes.startswith, with no range arguments, compiles this function.
    This function is only intended to be executed in this compiled form.

    Args:
        x: The bytes object to examine.
        prefix: The subsequence to look for.

    Returns:
        Result of check.
    """
def bytes_startswith(x: bytes, prefix: bytes) -> bool {
    if len(x) < len(prefix) {
        return False;
    }
    for (index, i) in enumerate(prefix) {
        if x[index] != i {
            return False;
        }
    }
    return True;
}

"""
    No-one likes timing attacks.

    This function should probably not be part of the public API, and thus will
    be deprecated in a future release to be replaced with a internal function.
    """
def time_independent_HMAC_compare(a: str, b: str) -> bool {
    if len(a) != len(b) {
        return False;
    }
    result = 0;
    (a, b) = (a.lower(), b.lower());
    for i in range(len(a)) {
        result |= ord(a[i]) ^ ord(b[i]);
    }
    return result == 0;
}

