"""
    Create a list of dictionaries from a whitespace and newline delimited text.

    For example, this:
    cpu 1100
    ram 640

    cpu 2200
    ram 1024

    becomes:
    [{'cpu': '1100', 'ram': '640'}, {'cpu': '2200', 'ram': '1024'}]
    """
def str2dicts(data: str) -> list[dict[str, str]] {
    list_data = [];
    list_data.append({});
    d = list_data[-1];
    for line in data.split('\n') {
        line = line.strip();
        if not line {
            d = {};
            list_data.append(d);
            d = list_data[-1];
            continue;
        }
        whitespace = line.find(' ');
        if not whitespace {
            continue;
        }
        key = line[0:whitespace];
        value = line[(whitespace + 1):];
        d.update({key: value});
    }
    return [val for val in list_data if val != {}];
}

"""
    Shuffles the character of a string by placing each of them
    in a grid (the height is dependent on the key) in a zigzag
    formation and reading it left to right.
    """
def encrypt(input_string: str, key: int) -> str {
    grid = [[] for _ in range(key)];
    lowest = key - 1;
    if key <= 0 {
        raise ValueError("Height of grid can't be 0 or negative");
    }
    if key == 1 or len(input_string) <= key {
        return input_string;
    }
    for (position, character) in enumerate(input_string) {
        num = position % (lowest * 2);
        num = min(num, (lowest * 2) - num);
        grid[num].append(character);
    }
    return "".join(["".join(row) for row in grid]);
}

