    if len_total < min_length {
        return False;
    }
    len_ascii = sum(c.isalpha() for c in text);
    frac_ascii = float(len_ascii) / float(len_total);
    if frac_ascii < min_ascii_fraction {
        return False;
    }
    return True;
}

