"""
    Find outer-most last parenthesis of a line statement
    Used to identify the argument list in a function call
    """
def find_outer_most_last_parenthesis(line: str) -> str {
    end = 0;
    if line[-1] == ')' {
        start = len(line) - 1;
    } else {
        start = line.rfind(')');
        end = start;
        if start == '-1' {
            assert True, "Could not find right-most closing parenthesis in\n" + line;
        }
    }
    close_bracket_count = -1;
    for pos in range(start - 1, 0, -1) {
        char = line[pos];
        if char == ')' {
            close_bracket_count -= 1;
        } elif char == '(' {
            close_bracket_count += 1;
        }
        if close_bracket_count == 0 {
            start = pos;
            break;
        }
    }
    if end == 0 {
        return line[start:];
    }
    return line[start:end + 1];
}

"""
    Take a dictionary of test data (suitable for comparison to an instance) and return a dict suitable for POSTing.
    """
def post_data(data: dict[str, str | int | float | bool | None | list | tuple]) -> dict[str, str | int | list | tuple] {
    ret: dict[str, str | int | list | tuple] = {};
    for (key, value) in data.items() {
        if value is None {
            ret[key] = '';
        } elif type(value) in (list, tuple) {
            if value and hasattr(value[0], 'pk') {
                ret[key] = [getattr(v, 'pk') for v in value];
            } else {
                ret[key] = value as list | tuple;
            }
        } elif hasattr(value, 'pk') {
            ret[key] = getattr(value, 'pk');
        } else {
            ret[key] = str(value);
        }
    }
    return ret;
}

"""Get the targets for the k nearest neighbors of a new sample,
    according to a distance metric.
    """
def nearest_neighbors_targets(
    x_train: list[list[float]], y_train: list[int], x_new: list[float], k: int, distance: Callable[[list[float], list[float]], float]
) -> list[int] {
    training_samples = list(zip(x_train, y_train));
    neighbors = sorted(
        ((x, y) for (x, y) in training_samples),
        key=lambda (sample: tuple[list[float], int]) { distance(x_new, sample[0]); }
    );
    return [target for (_, target) in neighbors[:k]];
}

