"""
  Replaces multiple slices of text with new values. This is a convenience method for making code
  modifications of ranges e.g. as identified by ``ASTTokens.get_text_range(node)``. Replacements is
  an iterable of ``(start, end, new_text)`` tuples.

  For example, ``replace("this is a test", [(0, 4, "X"), (8, 9, "THE")])`` produces
  ``"X is THE test"``.
  """
def replace(text: str, replacements: list[tuple[int, int, str]]) -> str {
    p = 0;
    parts: list[str] = [];
    for (start, end, new_text) in sorted(replacements) {
        parts.append(text[p:start]);
        parts.append(new_text);
        p = end;
    }
    parts.append(text[p:]);
    return "".join(parts);
}

"""Average for multiple evaluations.

    Args:
        evals [tuple]: several evals without limitation
        ndigits [int]: decimal number of float

    Returns:
        avg [dict]: dict of the average values of all the evaluation metrics
    """
def average_prfacc(*evals: Any, ndigits: Any = 4) -> object {
    avg = {}.fromkeys(evals[0].keys());
    for key in avg {
        values = [e[key] for e in evals];
        if isinstance(values[0], `dict) {
            avg[key] = average_prfacc(*values);
        } else {
            avg[key] = round((sum(values) / len(values)), ndigits);
        }
    }
    return avg;
}

