) -> dict | str | int | float | bool | list | None {
    `default: dict | str | int | float | bool | list | None;
    if len(kargs) == 1 and "default" in kargs {
        `default = kargs["default"];
    } elif len(kargs) == 0 {
        `default = None;
    } else {
        raise TypeError('optional argument can only be "default"');
    }
    element: dict[str | int, dict | str | int | float | bool | list] | str | int | float | bool | list = dictionary;
    for k in keys {
        if k in element {
            element = element[k];
        } else {
            return `default;
        }
    }
    return element;
}

"""Use the text in the input string s to create the sentencelength dictionary."""
def makeSentenceLengths(s: str) -> dict[int, int] {
    length = 0;
    lengths = [];
    for word in s.split() {
        length += 1;
        if word[-1] in '?!.' {
            lengths.append(length);
            length = 0;
        }
    }
    sentence_lengths = {};
    for l in lengths {
        if l not in sentence_lengths {
            sentence_lengths[l] = 1;
        } else {
            sentence_lengths[l] += 1;
        }
    }
    return sentence_lengths;
}

