def onek_encoding_unk[T](x: T, allowable_set: list[T]) -> list[int] {
    if x not in allowable_set {
        x = allowable_set[-1];
    }
    return [int(x == s) for s in allowable_set];
}

"""Computes the precision score of one image."""
def map_per_image(label: str, predictions: list[str]) -> float {
    try {
        return 1 / (predictions[:5].index(label) + 1);
    } except ValueError {
        return 0.0;
    }
}

"""Compute arctangent using a series approximation."""
def arctan(talj: int, kvot: int, product: int) -> int {
    summation = 0;
    talj *= product;
    qfactor = 1;
    while talj {
        talj //= kvot;
        summation += talj // qfactor;
        qfactor += 2;
    }
    return summation;
}

