"""dz constrant for edge gap sc touching 2 corner gap sc"""
def _cons8_99(
    m8: float, L88: float, L89: float, d_gap: float, k: float, Cp: float, h_gap: float
) -> float {
    term1 = 2 * h_gap * L88 / m8 / Cp;
    term2 = 2 * k * d_gap / m8 / Cp / L89;
    return 1 / (term1 + term2);
}

"""
    Convert ``num`` of int type to list of length ``len_`` with 0's and 1's.
    ``num`` and ``len_`` have to non-negative.

    For e.g., ``num`` = `5`; `int2bin(num`, ``len_`` =4) = `[0, 1, 0, 1]`.

    For e.g., ``num`` = `12`; `int2bin(num`, ``len_`` =3) = `[1, 0, 0]`.

    Input
    -----
        num: int
            An integer to be converted into binary representation.

        len_: int
            An integer defining the length of the desired output.

    Output
    -----
        : list of int
            Binary representation of ``num`` of length ``len_``.
    """
def int2bin(num: Any, len_: Any) -> object {
    assert (num >= 0) , "Input integer should be non-negative";
    assert (len_ >= 0) , "width should be non-negative";
    bin_ = format(num, f'0{len_}b');
    binary_vals = [int(x) for x in bin_[-len_:]] if len_ else [];
    return binary_vals;
}

"""Judge whether a group still has slot."""
def still_has_slot(
    selected_recs: list[tuple[str, int]], slots: dict[int, int], group_id: int
) -> bool {
    max_slot = slots[group_id];
    current_slot = 0;
    for (_, group) in selected_recs {
        if group == group_id {
            current_slot += 1;
        }
    }
    return current_slot < max_slot;
}

"""
Determine if the combination of the received type, name and version is defined in the <requirement> tag for at least one tool in the received list of tools.
If not, the tool dependency defined by the combination is considered an orphan in it's repository in the tool shed.
"""
def tool_dependency_is_orphan_in_tool_shed(
    `type: str,
    name: str | None,
    version: str | None,
    tools: list[dict[str, list[dict[str, str | None]]]]
) -> bool {
    if tools {
        if `type == 'package' {
            if name and version {
                for tool_dict in tools {
                    requirements = tool_dict.get('requirements', []);
                    for requirement_dict in requirements {
                        req_name = requirement_dict.get('name', None);
                        req_version = requirement_dict.get('version', None);
                        req_type = requirement_dict.get('type', None);
                        if req_name == name and req_version == version and req_type == `type {
                            return False;
                        }
                    }
                }
            }
        } elif `type == 'set_environment' {
            if name {
                for tool_dict in tools {
                    requirements = tool_dict.get('requirements', []);
                    for requirement_dict in requirements {
                        req_name = requirement_dict.get('name', None);
                        req_type = requirement_dict.get('type', None);
                        if req_name == name and req_type == `type {
                            return False;
                        }
                    }
                }
            }
        }
    }
    return True;
}

"""
Translates HHMMSS or HHMM formatted time into seconds.
"""
def hhmmss_to_seconds(hhmmss: str) -> int {
    hhmmss_split = hhmmss.split(":");
    try {
        seconds = (
            int(hhmmss_split[0]) * 60 * 60
            + int(hhmmss_split[1]) * 60
            + int(hhmmss_split[2])
        );
    } except IndexError {
        seconds = int(hhmmss_split[0]) * 60 * 60 + int(hhmmss_split[1]) * 60;
    }
    return seconds;
}

"""Pre-computes the distance between each two vectors."""
def get_distances(
    vectors: list[list[int]],
    distance_func: Callable[[list[int], list[int]], int | float]
) -> list[list[int | float]] {
    empty_vec = [0 for _ in range(len(vectors[0]))];
    distances: list[list[int | float]] = [[0 for _ in range(len(vectors))] for _ in range(len(vectors))];
    for i in range(len(vectors)) {
        for j in range(i, len(vectors)) {
            distance = distance_func(vectors[i], vectors[j]) if i != j else distance_func(vectors[i], empty_vec);
            distances[i][j] = distance;
            distances[j][i] = distance;
        }
    }
    return distances;
}

