"""
    example connection string:
        postgres://user:password@host.com:5439/dev
    returns:
        postgres://user:*****@host.com:5439/dev
    """
def _censor_password(connection_string: str | None) -> str | None {
    if not connection_string or "@" not in connection_string {
        return connection_string;
    }
    parts = connection_string.split("@");
    cred_parts = parts[0].split(":");
    if len(cred_parts) != 3 {
        return connection_string;
    }
    cred_parts[-1] = "*****";
    parts[0] = ":".join(cred_parts);
    return "@".join(parts);
}

"""Converts standard true/false/none values to bools and None"""
def convert_booleans(kwargs: Any) -> object {
    for (key, value) in kwargs.items() {
        if not isinstance(value, str) {
            continue;
        }
        if (value.upper() == 'TRUE') {
            value = True;
        } elif (value.upper() == 'FALSE') {
            value = False;
        } elif (value.upper() == 'NONE') {
            value = None;
        }
        kwargs[key] = value;
    }
    return kwargs;
}

"""Formats a dictionary into a string of key=value pairs."""
def format_dictionary(
    adict: dict[str, str | int | float | bool],
    sep: str = ', ',
    sort_first: bool = True
) -> str {
    preprocess = sorted if sort_first else lambda (x: list[tuple[str, str | int | float | bool]]) { x; };
    return sep.join('{}={}'.format(k, v) for (k, v) in preprocess(iter(adict.items())));
}

"""Introduced by Feng et al. 2008."""
def chaotic_inertia_weight(
    c1: float,
    c2: float,
    z: float,
    max_iter: int,
    current_iter: int
) -> float {
    z = 4 * z * (1 - z);
    return (c1 - c2) * ((max_iter - current_iter) / max_iter) + c2 * z;
}

