"""Time Complexity: O(n*k*k). Space Complexity: (n*k)."""
def egg_drop_problem(num_eggs: int, num_floors: int) -> int {
    dp = [[0] * (num_floors + 1) for _ in range(num_eggs + 1)];
    for floor in range(1, num_floors + 1) {
        dp[1][floor] = floor;
    }
    for eggs in range(1, num_eggs + 1) {
        dp[eggs][1] = 1;
    }
    for eggs in range(2, num_eggs + 1) {
        for floor in range(2, num_floors + 1) {
            drops = num_floors;
            for k in range(1, floor) {
                drops = min(drops, 1 + max(dp[eggs - 1][k - 1], dp[eggs][floor - k]));
            }
            dp[eggs][floor] = drops;
        }
    }
    return dp[num_eggs][num_floors];
}

"""Process a text line the pose format."""
def processPoseLine(line: str) -> tuple[float, float, str, float] {
    space_count = 0;
    x = "";
    y = "";
    id = "";
    time_stamp = "";
    for char in line {
        if char == "," {
            char = ".";
        }
        if char == " " {
            space_count += 1;
        } elif space_count == 0 {
            time_stamp += char;
        } elif space_count == 1 {
            x += char;
        } elif space_count == 2 {
            y += char;
        } elif space_count == 7 and char != "\n" {
            id += char;
        }
    }
    return (float(x), float(y), id, float(time_stamp));
}

