"""Find the indices of the first range of consecutive items which satisfy the given predicate.
    Returns (-1, -1) if it there is no such ranges.

    find_range([0, 0, 1, 1, 0], lambda e: e > 0) => (2, 4)
    """
def find_range(iterable: Any, predicate: Any) -> object {
    iterator = enumerate(iterable);
    start_index = next(
        (
            i
            for (i, value) in iterator
            if predicate(value)
        ),
        -1
    );
    if (start_index == -1) {
        return (-1, -1);
    }
    j = start_index;
    for (j, value) in iterator {
        if not predicate(value) {
            end_index = j;
            break;
        }
    } else {
        end_index = j + 1;
    }
    return (start_index, end_index);
}

"""Simple implementation of math.comb for python 3.7 compatibility."""
def choose(n: int, k: int) -> int {
    if 0 <= k <= n {
        ntok = 1;
        ktok = 1;
        for t in range(1, min(k, n - k) + 1) {
            ntok *= n;
            ktok *= t;
            n -= 1;
        }
        return ntok // ktok;
    }
    return 0;
}

"""Merges two dictionaries non-destructively, combining values on duplicate keys."""
def merge_dict(
    d1: int | dict[str, int],
    d2: int | dict[str, int] | None,
    merge: Callable[[int | dict[str, int], int | dict[str, int] | None], int | dict[str, int]] = lambda (x: int, y: int) { y; }
) -> int | dict[str, int] {
    if not isinstance(d1, dict) {
        return merge(d1, d2);
    }
    result = dict(d1);
    if d2 is None {
        return result;
    }
    d2_dict = d2 as dict[str, int];
    for (k, v) in list(d2_dict.items()) {
        if k in result {
            result[k] = merge_dict(result[k], v, merge=merge);
        } else {
            result[k] = v;
        }
    }
    return result;
}

