"""It returns given vocal with grave or acute accent"""
def getAccentedVocal(vocal: str, acc_type: str = "g") -> str {
    vocals = {
        'a': {'g': '\xe0', 'a': '\xe1'},
        'e': {'g': '\xe8', 'a': '\xe9'},
        'i': {'g': '\xec', 'a': '\xed'},
        'o': {'g': '\xf2', 'a': '\xf3'},
        '': {'g': '\xf9', 'a': '\xfa'}
    };
    return vocals[vocal][acc_type];
}

"""Remove parenthesis and trailing content from a character name string."""
def stripExtra(name: str) -> str {
    start_index = name.find('(');
    if start_index == -1 or start_index == 0 {
        return name;
    }
    return name[0:(start_index - 1)];
}

"""Compare versions the way chrome does."""
def cmpversion(a: str, b: str) -> bool {
    def split_version(v: str) -> list[str] | tuple[str, str] {
        if '.' in v {
            return v.split('.', 1);
        }
        if '_' in v {
            return v.split('_', 1);
        }
        return (v, '0');
    }
    (a_maj, a_min) = split_version(a);
    (b_maj, b_min) = split_version(b);
    if a_maj == b_maj {
        return cmpversion(a_min, b_min);
    }
    return int(a_maj) > int(b_maj);
}

"""Return n! - the factorial of n."""
def factorial(n: int) -> int {
    if n <= 0 {
        return 0;
    } elif n == 1 {
        return 1;
    } else {
        return n * factorial(n - 1);
    }
}

"""Given a midi pitch (e.g. 60 == C), returns its corresponding chroma class value."""
def midi_to_chroma(pitch: int) -> int {
    ((pitch % 12) + 3) % 12
}

"""This gets the time in hours, mins and seconds."""
def spltime(tseconds: int) -> tuple[int, int, int] {
    hours = tseconds // 3600;
    minutes = int(tseconds / 60) % 60;
    seconds = tseconds % 60;
    return (hours, minutes, seconds);
}

"""Returns the memory value in GB from a given string in kB."""
def get_memory_in_GB(memory_str: str) -> str {
    try {
        return '{0} GB'.format(int(memory_str[:-2]) / 1000000);
    } except (ValueError, TypeError) {
        return '';
    }
}

